window.__finlexDocLoaded(10037,{"id":10037,"articles":[{"id":1000092,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with special considerations that apply to a group audit, including a risk-based approach to scoping components and directing, supervising, and reviewing component auditors.","seq":0},{"id":1000093,"no":"ISA 600.16–59","heading":"Risk-Based Group Audits & Component Auditors","text":"• Removes the legacy 'significant component' full-scope bright line in favour of a risk-based scoping approach aligned with ISA 315.\n• Group engagement partner retains sole responsibility for direction, supervision, and review of component auditors, determining component performance materiality (lower than group materiality), and evaluating sufficiency of group audit evidence (converged with China CSA 1401).","seq":1},{"id":1000094,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
